const u=t=>new Promise(e=>setTimeout(e,t)),l=t=>JSON.parse(JSON.stringify(t)),y=t=>!!(t==null||typeof t=="string"&&t.trim()===""||Array.isArray(t)&&t.length===0||typeof t=="object"&&Object.keys(t).length===0),d=t=>{if(t=parseInt(t,10),t===0)return"영원정";const e=["","만","억","조","경"],f=["","십","백","천"],c=["","일","이","삼","사","오","육","칠","팔","구"];let n="",o=0;for(;t>0;){const p=t%1e4;t=Math.floor(t/1e4);let s="";const a=p.toString().padStart(4,"0");for(let r=0;r<4;r++){const i=parseInt(a[r]);i>0&&(s+=c[i]+f[3-r])}s!==""&&(n=s+e[o]+n),o++}return n+" 원정"};export{l as d,y as e,d as n,u as w};
